222	    fun loadStreamState(queueItem: PlayQueueItem): Maybe<StreamStateEntity> {
223	        return queueItem.stream
224	            .map { info -> streamTable.upsert(StreamEntity(info)) }
225	            .flatMapPublisher { streamId -> streamStateTable.getState(streamId) }
226	            .firstElement()
227	            .flatMap { list -> if (list.isEmpty()) Maybe.empty() else Maybe.just(list[0]) }
228	            .filter { state -> state.isValid(queueItem.duration) }
229	            .subscribeOn(Schedulers.io())
230	    }
231	
232	    fun loadStreamState(info: StreamInfo): Maybe<StreamStateEntity> {
233	        return Single.fromCallable { streamTable.upsert(StreamEntity(info)) }
234	            .flatMapPublisher { streamId -> streamStateTable.getState(streamId) }
235	            .firstElement()
236	            .flatMap { list -> if (list.isEmpty()) Maybe.empty() else Maybe.just(list[0]) }
237	            .filter { state -> state.isValid(info.duration) }
238	            .subscribeOn(Schedulers.io())
239	    }
240	
241	    fun loadStreamState(info: InfoItem): Maybe<StreamStateEntity> {
242	        return Maybe.fromCallable {
243	            streamTable.getStream(info.serviceId.toLong(), info.url)
244	                .blockingFirst()
245	                .firstOrNull()
246	                ?.let { entity ->
247	                    streamStateTable.getState(entity.uid)
248	                        .blockingFirst()
249	                        .firstOrNull()
250	                }
251	        }.subscribeOn(Schedulers.io())
252	    }
253	
254	    fun loadLocalStreamStateBatch(items: List<LocalItem>): Single<List<StreamStateEntity?>> {
255	        return Single.fromCallable {
256	            items.map { item ->
257	                val streamId = when (item) {
258	                    is StreamStatisticsEntry -> item.streamId
259	                    is PlaylistStreamEntity -> item.streamUid
260	                    is PlaylistStreamEntry -> item.streamId
261	                    else -> return@map null
262	                }
263	
264	                streamStateTable.getState(streamId)
265	                    .blockingFirst()
266	                    .firstOrNull()
267	            }
268	        }.subscribeOn(Schedulers.io())
269	    }
270	
271	    fun saveStreamState(info: StreamInfo, progressMillis: Long): Completable {
272	        return rxCompletable(Dispatchers.IO) {
273	            database.withWriteTransaction {
274	                val streamId = streamTable.upsert(StreamEntity(info))
275	                val state = StreamStateEntity(streamId, progressMillis)
276	                if (state.isValid(info.duration)) {
277	                    streamStateTable.upsert(state)
278	                }
279	            }

