31	    fun createPlaylist(name: String, streams: List<StreamEntity>): Maybe<List<Long>> {
32	        // Disallow creation of empty playlists
33	        if (streams.isEmpty()) {
34	            return Maybe.empty()
35	        }
36	
37	        // Save to the database directly.
38	        // Make sure the new playlist is always on the top of bookmark.
39	        // The index will be reassigned to non-negative number in BookmarkFragment.
40	        return rxMaybe(Dispatchers.IO) {
41	            database.withWriteTransaction {
42	                val streamIds = streamTable.upsertAll(streams)
43	                val newPlaylist = PlaylistEntity(
44	                    name = name,
45	                    isThumbnailPermanent = false,
46	                    thumbnailStreamId = streamIds[0],
47	                    displayIndex = -1
48	                )
49	                insertJoinEntities(playlistTable.insert(newPlaylist), streamIds, 0)
50	            }
51	        }
52	    }
53	
54	    fun appendToPlaylist(playlistId: Long, streams: List<StreamEntity>): Maybe<List<Long>> {
55	        return playlistStreamTable.getMaximumIndexOf(playlistId)
56	            .firstElement()
57	            .map { maxJoinIndex ->
58	                runBlocking {
59	                    database.withWriteTransaction<List<Long>> {
60	                        val streamIds = streamTable.upsertAll(streams)
61	                        insertJoinEntities(playlistId, streamIds, maxJoinIndex + 1)
62	                    }
63	                }
64	            }.subscribeOn(Schedulers.io())
65	    }
66	
67	    private fun insertJoinEntities(
68	        playlistId: Long,
69	        streamIds: List<Long>,
70	        indexOffset: Int
71	    ): List<Long> {
72	        val entities = streamIds.mapIndexed { index, streamId ->
73	            PlaylistStreamEntity(playlistId, streamId, index + indexOffset)
74	        }
75	        return playlistStreamTable.insertAll(entities)
76	    }
77	
78	    fun updateJoin(playlistId: Long, streamIds: List<Long>): Completable {
79	        val joinEntities = streamIds.mapIndexed { index, streamId ->
80	            PlaylistStreamEntity(playlistId, streamId, index)
81	        }
82	
83	        return Completable.fromRunnable {
84	            playlistStreamTable.updatePlaylistStreams(playlistId, joinEntities)
85	        }.subscribeOn(Schedulers.io())
86	    }
