119	    fun getPlaylistStreams(playlistId: Long): Flowable<MutableList<PlaylistStreamEntry>> {
120	        return playlistStreamTable.getOrderedStreamsOf(playlistId).subscribeOn(Schedulers.io())
121	    }
122	
123	    fun renamePlaylist(playlistId: Long, name: String): Maybe<Int> {
124	        return modifyPlaylist(playlistId, name, THUMBNAIL_ID_LEAVE_UNCHANGED, false)
125	    }
126	
127	    fun changePlaylistThumbnail(
128	        playlistId: Long,
129	        thumbnailStreamId: Long,
130	        isPermanent: Boolean
131	    ): Maybe<Int> {
132	        return modifyPlaylist(playlistId, null, thumbnailStreamId, isPermanent)
133	    }
134	
135	    fun getPlaylistThumbnailStreamId(playlistId: Long): Long {
136	        return playlistTable.getPlaylist(playlistId).blockingFirst()[0].thumbnailStreamId
137	    }
138	
139	    fun getIsPlaylistThumbnailPermanent(playlistId: Long): Boolean {
140	        return playlistTable.getPlaylist(playlistId).blockingFirst()[0].isThumbnailPermanent
141	    }
142	
143	    fun getAutomaticPlaylistThumbnailStreamId(playlistId: Long): Long {
144	        val streamId = playlistStreamTable.getAutomaticThumbnailStreamId(playlistId)
145	            .blockingFirst()
146	        return if (streamId < 0) PlaylistEntity.DEFAULT_THUMBNAIL_ID else streamId
147	    }
148	
149	    private fun modifyPlaylist(
150	        playlistId: Long,
151	        name: String?,
152	        thumbnailStreamId: Long,
153	        isPermanent: Boolean
154	    ): Maybe<Int> {
155	        return playlistTable.getPlaylist(playlistId)
156	            .firstElement()
157	            .filter { playlistEntities -> playlistEntities.isNotEmpty() }
158	            .map { playlistEntities ->
159	                val playlist = playlistEntities[0]
160	                if (name != null) {
161	                    playlist.name = name
162	                }
163	                if (thumbnailStreamId != THUMBNAIL_ID_LEAVE_UNCHANGED) {
164	                    playlist.thumbnailStreamId = thumbnailStreamId
165	                    playlist.isThumbnailPermanent = isPermanent
166	                }
167	                playlistTable.update(playlist)
168	            }.subscribeOn(Schedulers.io())
169	    }
170	
171	    fun hasPlaylists(): Maybe<Boolean> {
172	        return playlistTable.count
173	            .firstElement()
174	            .map { count -> count > 0 }
175	            .subscribeOn(Schedulers.io())
176	    }
177	
178	    companion object {
179	        private const val THUMBNAIL_ID_LEAVE_UNCHANGED = -2L
180	    }
181	}
