4	
5	class UrlFinder {
6	    companion object {
7	        private val WEB_URL_WITH_PROTOCOL = Pattern.compile(PatternsCompat.WEB_URL_WITH_PROTOCOL)
8	
9	        /**
10	         * @return the first url found in the input, null otherwise.
11	         */
12	        @JvmStatic
13	        fun firstUrlFromInput(input: String?): String? {
14	            if (input.isNullOrEmpty()) {
15	                return null
16	            }
17	
18	            val matcher = WEB_URL_WITH_PROTOCOL.matcher(input)
19	
20	            if (matcher.find()) {
21	                return matcher.group()
22	            }
23	
24	            return null
25	        }
26	    }
27	}
