413	    private fun handleLoadedState(loadedState: FeedState.LoadedState) {
414	        val itemVersion = when (getItemViewMode(requireContext())) {
415	            ItemViewMode.GRID -> StreamItem.ItemVersion.GRID
416	            ItemViewMode.CARD -> StreamItem.ItemVersion.CARD
417	            else -> StreamItem.ItemVersion.NORMAL
418	        }
419	        loadedState.items.forEach { it.itemVersion = itemVersion }
420	
421	        // This need to be saved in a variable as the update occurs async
422	        val oldOldestSubscriptionUpdate = oldestSubscriptionUpdate
423	
424	        groupAdapter.updateAsync(loadedState.items, false) {
425	            oldOldestSubscriptionUpdate?.run {
426	                highlightNewItemsAfter(oldOldestSubscriptionUpdate)
427	            }
428	        }
429	
430	        listState?.run {
431	            feedBinding.itemsList.layoutManager?.onRestoreInstanceState(listState)
432	            listState = null
433	        }
434	
435	        val feedsNotLoaded = loadedState.notLoadedCount > 0
436	        feedBinding.refreshSubtitleText.isVisible = feedsNotLoaded
437	        if (feedsNotLoaded) {
438	            feedBinding.refreshSubtitleText.text = getString(
439	                R.string.feed_subscription_not_loaded_count,
440	                loadedState.notLoadedCount
441	            )
442	        }
443	
444	        if (oldestSubscriptionUpdate != loadedState.oldestUpdate ||
445	            (oldestSubscriptionUpdate == null && loadedState.oldestUpdate == null)
446	        ) {
447	            // ignore errors if they have already been handled for the current update
448	            handleItemsErrors(loadedState.itemsErrors)
449	        }
450	        oldestSubscriptionUpdate = loadedState.oldestUpdate
451	
452	        if (loadedState.items.isEmpty()) {
453	            showEmptyState()
454	        } else {
455	            hideLoading()
456	        }
457	    }
