469	    private fun handleItemsErrors(errors: List<Throwable>) {
470	        errors.forEachIndexed { i, t ->
471	            if (t is FeedLoadService.RequestException &&
472	                t.cause is ContentNotAvailableException
473	            ) {
474	                disposables.add(
475	                    Single.fromCallable {
476	                        NewPipeDatabase.getInstance(requireContext()).subscriptionDAO()
477	                            .getSubscription(t.subscriptionId)
478	                    }
479	                        .subscribeOn(Schedulers.io())
480	                        .observeOn(AndroidSchedulers.mainThread())
481	                        .subscribe(
482	                            { subscriptionEntity ->
483	                                handleFeedNotAvailable(
484	                                    subscriptionEntity,
485	                                    t.cause,
486	                                    errors.subList(i + 1, errors.size)
487	                                )
488	                            },
489	                            { throwable -> Log.e(TAG, "Unable to process", throwable) }
490	                        )
491	                )
492	                // this will be called on the remaining errors by handleFeedNotAvailable()
493	                return@handleItemsErrors
494	            }
495	        }
496	
497	        if (errors.isNotEmpty()) {
498	            // if no error was a ContentNotAvailableException, show a general error snackbar
499	            ErrorUtil.showSnackbar(this, ErrorInfo(errors, UserAction.REQUESTED_FEED, ""))
500	        }
501	    }
502	
503	    private fun handleFeedNotAvailable(
504	        subscriptionEntity: SubscriptionEntity,
505	        cause: Throwable?,
506	        nextItemsErrors: List<Throwable>
507	    ) {
508	        val sharedPreferences = PreferenceManager.getDefaultSharedPreferences(requireContext())
509	        val isFastFeedModeEnabled = sharedPreferences.getBoolean(
510	            getString(R.string.feed_use_dedicated_fetch_method_key),
511	            false
512	        )
513	
514	        val builder = AlertDialog.Builder(requireContext())
515	            .setTitle(R.string.feed_load_error)
516	            .setPositiveButton(R.string.unsubscribe) { _, _ ->
517	                SubscriptionManager(requireContext())
518	                    .deleteSubscription(subscriptionEntity.serviceId, subscriptionEntity.url!!)
519	                    .subscribe()
520	                handleItemsErrors(nextItemsErrors)
521	            }
522	            .setNegativeButton(R.string.cancel, null)
523	
524	        var message = getString(R.string.feed_load_error_account_info, subscriptionEntity.name)
525	        if (cause is AccountTerminatedException) {
526	            message += "\n" + getString(R.string.feed_load_error_terminated)
527	        } else if (cause is ContentNotAvailableException) {
528	            if (isFastFeedModeEnabled) {
529	                message += "\n" + getString(R.string.feed_load_error_fast_unknown)
530	                builder.setNeutralButton(R.string.feed_use_dedicated_fetch_method_disable_button) { _, _ ->
531	                    sharedPreferences.edit {
532	                        putBoolean(getString(R.string.feed_use_dedicated_fetch_method_key), false)
533	                    }
534	                }
535	            } else if (!isNullOrEmpty(cause.message)) {
536	                message += "\n" + cause.message
537	            }
538	        }
539	        builder.setMessage(message)
540	            .show()
541	    }
542	
543	    private fun updateRelativeTimeViews() {
544	        updateRefreshViewState()

125	        return rxMaybe(Dispatchers.IO) {
126	            database.withWriteTransaction {
127	                val streamId = streamTable.upsert(StreamEntity(info))
128	                val latestEntry = streamHistoryTable.getLatestEntry(streamId)
129	
130	                if (latestEntry != null) {
131	                    streamHistoryTable.delete(latestEntry)
132	                    latestEntry.accessDate = currentTime
133	                    latestEntry.repeatCount = latestEntry.repeatCount + 1
134	                    streamHistoryTable.insert(latestEntry)
135	                } else {
136	                    // just viewed for the first time: set 1 view
137	                    streamHistoryTable.insert(StreamHistoryEntity(streamId, currentTime, 1))
138	                }
139	            }

