fun loadStreamState(queueItem: PlayQueueItem): Maybe<StreamStateEntity> {
    return queueItem.stream
        .map { info -> streamTable.upsert(StreamEntity(info)) }
        .flatMapPublisher { streamId -> streamStateTable.getState(streamId) }
